Properties props = new Properties();
props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "kafka-broker.internal:9092");
props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, ByteArraySerializer.class.getName());

// Enterprise Reliability Settings
props.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "true");
props.put(ProducerConfig.ACKS_CONFIG, "all"); // Wait for full in-sync replica ack
props.put(ProducerConfig.RETRIES_CONFIG, Integer.MAX_VALUE);
props.put(ProducerConfig.MAX_IN_FLIGHT_REQUESTS_PER_CONNECTION, "5");
props.put(ProducerConfig.COMPRESSION_TYPE_CONFIG, "snappy");

Producer<String, byte[]> producer = new KafkaProducer<>(props);

// Partition key guarantees all events for this user land in same partition
ProducerRecord<String, byte[]> record = new ProducerRecord<>(
    "orders.v1",
    order.getUserId(), // Key used for MurmurHash2 partition routing
    serializeToAvro(order)
);
producer.send(record);
